sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.selectedCase = null;
    c.processing = false;

    c.showFeedback = false;
    c.employeeFeedback = "";

    c.successMessage = "";
    c.errorMessage = "";


    // ----------------------------------
    // OPEN CASE DETAILS
    // ----------------------------------

    c.openCase = function(item) {

        c.selectedCase = item;

        c.showFeedback = false;
        c.employeeFeedback = "";

        c.successMessage = "";
        c.errorMessage = "";
    };


    // ----------------------------------
    // CLOSE CASE DETAILS
    // ----------------------------------

    c.closeCase = function() {

        c.selectedCase = null;

        c.showFeedback = false;
        c.employeeFeedback = "";

        c.successMessage = "";
        c.errorMessage = "";
    };


    // ----------------------------------
    // SHOW FEEDBACK FORM
    // ----------------------------------

    c.showFeedbackForm = function() {

        c.showFeedback = true;

        c.successMessage = "";
        c.errorMessage = "";
    };


    // ----------------------------------
    // CANCEL FEEDBACK
    // ----------------------------------

    c.cancelFeedback = function() {

        c.showFeedback = false;
        c.employeeFeedback = "";
        c.errorMessage = "";
    };


    // ==================================
    // ACCEPT HR RESOLUTION
    // ==================================

    c.acceptResolution = function(item) {

        c.successMessage = "";
        c.errorMessage = "";

        if (c.processing) {
            return;
        }

        c.processing = true;


        c.server.get({

            action: 'accept_resolution',

            sys_id: item.sys_id

        }).then(function(response) {

            c.processing = false;


            if (response.data.error) {

                c.errorMessage =
                    response.data.message ||
                    "Unable to confirm the resolution.";

                return;
            }


            if (response.data.success) {

                c.successMessage =
                    response.data.message;


                // Refresh complete case list
                c.data.cases =
                    response.data.cases;


                c.data.totalCases =
                    response.data.totalCases;

                c.data.openCases =
                    response.data.openCases;

                c.data.inProgressCases =
                    response.data.inProgressCases;

                c.data.resolvedCases =
                    response.data.resolvedCases;


                // Find refreshed selected case
                for (
                    var i = 0;
                    i < c.data.cases.length;
                    i++
                ) {

                    if (
                        c.data.cases[i].sys_id ==
                        item.sys_id
                    ) {

                        c.selectedCase =
                            c.data.cases[i];

                        break;
                    }
                }


                c.showFeedback = false;
                c.employeeFeedback = "";
            }

        }, function() {

            c.processing = false;

            c.errorMessage =
                "Unable to confirm the resolution. Please try again.";

        });

    };


    // ==================================
    // REJECT HR RESOLUTION
    // ==================================

    c.rejectResolution = function(item) {

        c.successMessage = "";
        c.errorMessage = "";


        if (
            !c.employeeFeedback ||
            !c.employeeFeedback.trim()
        ) {

            c.errorMessage =
                "Please explain why you still need HR support.";

            return;
        }


        if (c.processing) {
            return;
        }


        c.processing = true;


        c.server.get({

            action: 'reject_resolution',

            sys_id: item.sys_id,

            feedback:
                c.employeeFeedback

        }).then(function(response) {

            c.processing = false;


            if (response.data.error) {

                c.errorMessage =
                    response.data.message ||
                    "Unable to send your feedback.";

                return;
            }


            if (response.data.success) {

                c.successMessage =
                    response.data.message;


                // Refresh case list
                c.data.cases =
                    response.data.cases;


                c.data.totalCases =
                    response.data.totalCases;

                c.data.openCases =
                    response.data.openCases;

                c.data.inProgressCases =
                    response.data.inProgressCases;

                c.data.resolvedCases =
                    response.data.resolvedCases;


                // Refresh currently selected case
                for (
                    var i = 0;
                    i < c.data.cases.length;
                    i++
                ) {

                    if (
                        c.data.cases[i].sys_id ==
                        item.sys_id
                    ) {

                        c.selectedCase =
                            c.data.cases[i];

                        break;
                    }
                }


                c.showFeedback = false;
                c.employeeFeedback = "";
            }

        }, function() {

            c.processing = false;

            c.errorMessage =
                "Unable to send your feedback. Please try again.";

        });

    };

};

sp_widget.css:
.mhr-page {
  max-width: 1250px;
  margin: 0 auto;
  min-height: 100vh;
  padding: 34px 28px 60px;
  background: #f7f9fc;
  color: #10204a;
  font-family: Arial, sans-serif;
}


/* ==================================================
   HEADER
   ================================================== */

.mhr-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.mhr-header h2 {
  margin: 0 0 6px;
  font-size: 29px;
  font-weight: 700;
  color: #10204a;
}

.mhr-header p {
  margin: 0;
  color: #7c8599;
  font-size: 13px;
}

.mhr-back {
  color: #1769df !important;
  text-decoration: none !important;
  font-size: 13px;
}

.mhr-back:hover {
  text-decoration: underline !important;
}


/* ==================================================
   STATS
   ================================================== */

.mhr-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  margin-bottom: 22px;
}

.mhr-stat-card {
  background: #ffffff;
  border: 1px solid #e0e5ee;
  border-radius: 13px;
  padding: 19px;
  box-shadow: 0 3px 10px rgba(20,40,80,.04);
}

.mhr-stat-card span {
  display: block;
  color: #818a9e;
  font-size: 11px;
  margin-bottom: 7px;
}

.mhr-stat-card strong {
  font-size: 27px;
  color: #10204a;
}


/* ==================================================
   MAIN CARD
   ================================================== */

.mhr-card,
.mhr-details-card {
  background: #ffffff;
  border: 1px solid #e1e6ee;
  border-radius: 14px;
  padding: 20px;
  box-shadow: 0 3px 12px rgba(20,40,80,.05);
  margin-bottom: 20px;
}

.mhr-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.mhr-card-header h3 {
  margin: 0 0 4px;
  font-size: 18px;
  color: #10204a;
}

.mhr-card-header p {
  margin: 0;
  color: #828b9e;
  font-size: 11px;
}


/* ==================================================
   SEARCH
   ================================================== */

.mhr-search {
  width: 270px;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid #dfe4ec;
  border-radius: 9px;
  padding: 9px 11px;
  background: #ffffff;
}

.mhr-search input {
  width: 100%;
  border: none;
  outline: none;
  background: transparent;
  font-size: 12px;
  color: #293551;
}


/* ==================================================
   TABLE
   ================================================== */

.mhr-table-wrap {
  overflow-x: auto;
}

.mhr-table {
  width: 100%;
  border-collapse: collapse;
}

.mhr-table th {
  background: #f6f8fb;
  padding: 11px 10px;
  text-align: left;
  font-size: 11px;
  color: #36405c;
  white-space: nowrap;
}

.mhr-table td {
  padding: 12px 10px;
  border-bottom: 1px solid #edf0f4;
  font-size: 12px;
  color: #293551;
  vertical-align: middle;
}

.mhr-table tbody tr:hover {
  background: #fafbfe;
}


/* ==================================================
   BADGES
   ================================================== */

.priority-pill,
.status-pill {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 14px;
  font-size: 10px;
  font-weight: 600;
}

.priority-high {
  background: #fde7e6;
  color: #d53d35;
}

.priority-medium {
  background: #fff1d8;
  color: #d27b00;
}

.priority-low {
  background: #e4f5eb;
  color: #178458;
}

.status-open {
  background: #fff1dd;
  color: #ca7600;
}

.status-progress {
  background: #e5efff;
  color: #2b70d9;
}

/* NEW STATUS */

.status-awaiting {
  background: #fff4d6;
  color: #a35d00;
}

.status-resolved {
  background: #e2f6eb;
  color: #158659;
}

.status-closed {
  background: #edf0f4;
  color: #646d7e;
}


/* ==================================================
   VIEW BUTTON
   ================================================== */

.view-btn {
  border: 0;
  background: #0b8793;
  color: white;
  border-radius: 7px;
  padding: 6px 13px;
  font-size: 11px;
  cursor: pointer;
  transition: .2s;
}

.view-btn:hover {
  background: #076f78;
}


/* ==================================================
   DETAILS
   ================================================== */

.mhr-details-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 20px;
}

.mhr-details-header h3 {
  margin: 0 0 4px;
  color: #10204a;
}

.mhr-details-header p {
  margin: 0;
  color: #838ca0;
}

.close-btn {
  border: 0;
  background: #eef2f6;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  cursor: pointer;
  color: #36405c;
  transition: .2s;
}

.close-btn:hover {
  background: #e2e8f0;
}

.mhr-detail-grid {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: 16px;
  margin-bottom: 22px;
}

.mhr-detail-grid > div {
  padding: 14px;
  background: #f8f9fc;
  border-radius: 9px;
  border: 1px solid #eef1f5;
}

.mhr-detail-grid span {
  display: block;
  color: #848da0;
  font-size: 10px;
  margin-bottom: 6px;
}

.mhr-detail-grid strong {
  font-size: 13px;
  color: #10204a;
}


/* ==================================================
   REQUEST / RESOLUTION
   ================================================== */

.detail-section {
  margin-top: 18px;
}

.detail-section label {
  display: block;
  font-weight: 700;
  font-size: 12px;
  margin-bottom: 8px;
  color: #10204a;
}

.request-box {
  padding: 15px;
  min-height: 85px;
  background: #f7f9fc;
  border: 1px solid #e2e7ef;
  border-radius: 9px;
  line-height: 1.6;
  color: #293551;
}

.resolution-box {
  padding: 15px;
  min-height: 85px;
  background: #edf9f3;
  border: 1px solid #cce9db;
  color: #246044;
  border-radius: 9px;
  line-height: 1.7;
  white-space: pre-line;
}


/* ==================================================
   OPEN / IN PROGRESS
   ================================================== */

.waiting-box {
  margin-top: 18px;
  padding: 14px;
  background: #fff5e5;
  color: #9d6400;
  border-radius: 9px;
  border: 1px solid #efd9b1;
  font-size: 12px;
}


/* ==================================================
   EMPLOYEE CONFIRMATION
   ================================================== */

.employee-confirmation {
  margin-top: 22px;
  padding: 20px;
  border: 1px solid #bde5d2;
  border-left: 4px solid #0b8793;
  border-radius: 11px;
  background: #fbfffd;
}

.confirmation-heading {
  margin-bottom: 18px;
}

.confirmation-heading h4 {
  margin: 8px 0 6px;
  color: #10204a;
  font-size: 18px;
}

.confirmation-heading p {
  margin: 0;
  color: #748095;
  font-size: 12px;
  line-height: 1.6;
}

.resolution-badge {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 15px;
  background: #dff7ea;
  color: #168055;
  font-size: 10px;
  font-weight: 700;
}


/* ==================================================
   CONFIRMATION QUESTION
   ================================================== */

.confirmation-question {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid #e3e9ee;
}

.confirmation-question h4 {
  margin: 0 0 6px;
  font-size: 16px;
  color: #10204a;
}

.confirmation-question p {
  margin: 0 0 16px;
  color: #7c8599;
  font-size: 12px;
}

.confirmation-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}


/* ==================================================
   ACCEPT / NEED HELP BUTTONS
   ================================================== */

.accept-btn,
.need-help-btn,
.cancel-btn,
.submit-feedback-btn {
  border-radius: 8px;
  padding: 10px 16px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: .2s;
}

.accept-btn {
  border: 1px solid #15945f;
  background: #15945f;
  color: white;
}

.accept-btn:hover {
  background: #10794d;
}

.need-help-btn {
  border: 1px solid #d24a43;
  background: #ffffff;
  color: #c8423a;
}

.need-help-btn:hover {
  background: #fff2f1;
}


/* ==================================================
   FEEDBACK FORM
   ================================================== */

.feedback-section {
  margin-top: 20px;
  padding: 18px;
  background: #f8f9fc;
  border: 1px solid #e1e6ee;
  border-radius: 10px;
}

.feedback-section h4 {
  margin: 0 0 6px;
  color: #10204a;
  font-size: 15px;
}

.feedback-section p {
  margin: 0 0 12px;
  color: #7c8599;
  font-size: 11px;
}

.feedback-section textarea {
  width: 100%;
  min-height: 105px;
  padding: 12px;
  border: 1px solid #d6dde7;
  border-radius: 8px;
  resize: vertical;
  outline: none;
  font-size: 12px;
  color: #293551;
  background: #ffffff;
}

.feedback-section textarea:focus {
  border-color: #0b8793;
  box-shadow: 0 0 0 2px rgba(11,135,147,.08);
}

.feedback-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 13px;
}

.cancel-btn {
  border: 1px solid #dce2ea;
  background: #ffffff;
  color: #4f596d;
}

.cancel-btn:hover {
  background: #f3f5f8;
}

.submit-feedback-btn {
  border: 1px solid #0b8793;
  background: #0b8793;
  color: white;
}

.submit-feedback-btn:hover {
  background: #076f78;
}


/* ==================================================
   RESOLVED SECTION
   ================================================== */

.resolved-section {
  margin-top: 22px;
  padding: 24px;
  text-align: center;
  background: #f4fcf7;
  border: 1px solid #cfeadb;
  border-radius: 11px;
}

.resolved-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #dff7ea;
  color: #168055;
  font-size: 25px;
  font-weight: 700;
}

.resolved-section h4 {
  margin: 0 0 6px;
  color: #10204a;
  font-size: 17px;
}

.resolved-section > p {
  margin: 0 0 12px;
  color: #748095;
  font-size: 12px;
}

.resolved-section .detail-section {
  text-align: left;
}


/* ==================================================
   SUCCESS / ERROR MESSAGES
   ================================================== */

.mhr-action-message {
  margin-top: 18px;
  padding: 12px 14px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
}

.mhr-action-message.success {
  background: #e5f8ed;
  color: #17663f;
  border: 1px solid #bfe8d0;
}

.mhr-action-message.error {
  background: #fdeaea;
  color: #b63d36;
  border: 1px solid #f0c3c0;
}


/* ==================================================
   DISABLED BUTTON
   ================================================== */

button:disabled {
  opacity: .55;
  cursor: not-allowed;
}


/* ==================================================
   EMPTY STATE
   ================================================== */

.empty-row {
  text-align: center !important;
  color: #949cad !important;
  padding: 25px !important;
}


/* ==================================================
   RESPONSIVE
   ================================================== */

@media (max-width: 900px) {

  .mhr-stats {
    grid-template-columns: repeat(2,1fr);
  }

  .mhr-detail-grid {
    grid-template-columns: repeat(2,1fr);
  }

}


@media (max-width: 600px) {

  .mhr-page {
    padding: 24px 14px 40px;
  }

  .mhr-header,
  .mhr-card-header {
    display: block;
  }

  .mhr-back {
    display: inline-block;
    margin-top: 12px;
  }

  .mhr-search {
    width: 100%;
    margin-top: 15px;
  }

  .mhr-stats,
  .mhr-detail-grid {
    grid-template-columns: 1fr;
  }

  .confirmation-actions,
  .feedback-actions {
    flex-direction: column;
  }

  .confirmation-actions button,
  .feedback-actions button {
    width: 100%;
  }

}

sp_widget.script:
(function() {


	data.backDashboard = "employee_dashboard";

	var currentUserId = gs.getUserID();

	var userGR = new GlideRecord('sys_user');

	if (userGR.get(currentUserId)) {

		var departmentId =
			userGR.getValue('department');

		if (departmentId) {

			var deptGR =
				new GlideRecord('cmn_department');

			if (deptGR.get(departmentId)) {

				var departmentHead =
					deptGR.getValue('dept_head');

				if (departmentHead == currentUserId) {

					data.backDashboard =
						"hod_dashboard";
				}
			}
		}
	}
    // ----------------------------------
    // CURRENT USER
    // ----------------------------------

    data.userId = gs.getUserID();
    data.userName = gs.getUserDisplayName();

    data.cases = [];
    data.totalCases = 0;
    data.openCases = 0;
    data.inProgressCases = 0;
    data.resolvedCases = 0;

    data.success = false;
    data.error = false;
    data.message = "";


    // ==================================================
    // EMPLOYEE ACCEPTS HR RESOLUTION
    // ==================================================

    if (input &&
        input.action == 'accept_resolution') {

        var acceptGR =
            new GlideRecord(
                'x_snc_unified_hr_0_hr_case'
            );

        if (!acceptGR.get(input.sys_id)) {

            data.error = true;
            data.message = "HR Case not found.";

        } else if (
            acceptGR.getValue('request_by') !=
            data.userId
        ) {

            data.error = true;

            data.message =
                "You are not authorized to update this HR case.";

        } else if (
            acceptGR.getValue('status') !=
            'awaiting_employee_confirmation'
        ) {

            data.error = true;

            data.message =
                "This HR case is not waiting for your confirmation.";

        } else {

            acceptGR.setValue(
                'status',
                'resolved'
            );

            if (
                acceptGR.isValidField(
                    'resolved_on'
                )
            ) {

                acceptGR.setValue(
                    'resolved_on',
                    new GlideDateTime().getValue()
                );
            }

            acceptGR.update();

            data.success = true;

            data.message =
                "Thank you. HR Case " +
                acceptGR.getDisplayValue('number') +
                " has been marked as resolved.";
        }
    }


    // ==================================================
    // EMPLOYEE REJECTS HR RESOLUTION
    // ==================================================

    if (input &&
        input.action == 'reject_resolution') {

        var feedback =
            (input.feedback || '')
                .toString()
                .trim();

        if (!feedback) {

            data.error = true;

            data.message =
                "Please explain why you still need HR support.";

        } else {

            var rejectGR =
                new GlideRecord(
                    'x_snc_unified_hr_0_hr_case'
                );

            if (!rejectGR.get(input.sys_id)) {

                data.error = true;
                data.message = "HR Case not found.";

            } else if (
                rejectGR.getValue('request_by') !=
                data.userId
            ) {

                data.error = true;

                data.message =
                    "You are not authorized to update this HR case.";

            } else if (
                rejectGR.getValue('status') !=
                'awaiting_employee_confirmation'
            ) {

                data.error = true;

                data.message =
                    "This HR case is not waiting for your confirmation.";

            } else {

                rejectGR.setValue(
                    'status',
                    'in_progress'
                );

                if (
                    rejectGR.isValidField(
                        'rejection_feedback'
                    )
                ) {

                    rejectGR.setValue(
                        'rejection_feedback',
                        feedback
                    );
                }

                rejectGR.update();

                data.success = true;

                data.message =
                    "Your feedback has been sent to HR. " +
                    "The case is now back in progress.";
            }
        }
    }


    // ----------------------------------
    // GET LOGGED-IN EMPLOYEE'S CASES
    // ----------------------------------

    var caseGR =
        new GlideRecord(
            'x_snc_unified_hr_0_hr_case'
        );

    caseGR.addQuery(
        'request_by',
        data.userId
    );

    caseGR.orderByDesc(
        'sys_created_on'
    );

    caseGR.query();


    while (caseGR.next()) {

        var statusValue =
            caseGR.getValue('status');

        var statusLabel =
            caseGR.getDisplayValue('status');


        // Friendly label fallback
        if (
            statusValue ==
            'awaiting_employee_confirmation'
        ) {

            statusLabel =
                'Awaiting Employee Confirmation';
        }


        // ----------------------------------
        // COUNTERS
        // ----------------------------------

        data.totalCases++;

        if (statusValue == 'open') {
            data.openCases++;
        }

        if (statusValue == 'in_progress') {
            data.inProgressCases++;
        }

        if (statusValue == 'resolved') {
            data.resolvedCases++;
        }


        // ----------------------------------
        // CREATED ON
        // ----------------------------------

        var createdOn =
            caseGR.getDisplayValue(
                'created_on'
            );

        if (!createdOn) {

            createdOn =
                caseGR.getDisplayValue(
                    'sys_created_on'
                );
        }


        // ----------------------------------
        // CASE DATA
        // ----------------------------------

        data.cases.push({

            sys_id:
                caseGR.getUniqueValue(),

            number:
                caseGR.getDisplayValue(
                    'number'
                ),

            category:
                caseGR.getDisplayValue(
                    'category'
                ),

            priority:
                caseGR.getDisplayValue(
                    'priority'
                ),

            status:
                statusLabel,

            status_value:
                statusValue,

            assignment_group:
                caseGR.getDisplayValue(
                    'assignment_group'
                ),

            assigned_to:
                caseGR.getDisplayValue(
                    'assigned_to'
                ),

            description:
                caseGR.getDisplayValue(
                    'description'
                ),

            resolution_notes:
                caseGR.getDisplayValue(
                    'resolution_notes'
                ),

            rejection_feedback:
                caseGR.getDisplayValue(
                    'rejection_feedback'
                ),

            resolution_proposed_on:
                caseGR.getDisplayValue(
                    'resolution_proposed_on'
                ),

            created_on:
                createdOn

        });
    }

})();
